static int selected_native_fetch(int sig,siginfo_t *si,ucontext_t *uc) {
    int result=npf_real_native_fetch(sig,si,uc);
    npf_fetch_return(result,sig,si,uc);
    if(result==1)npf_safe_prefix(sig,si,uc);
    return result;
}

static struct li2_native_pair_owner npf_owner_copy;
const struct li2_native_pair_owner *npf_owner_argument(const struct li2_native_pair_owner *o,uintptr_t pc) {
    if(npf_control_match(17,0,NPF_PREPARED,pc)) {
        npf_stage_observe(NPF_CONTROL_BEFORE,pc,0);
        copy(&npf_owner_copy,&np_owner,sizeof npf_owner_copy);
        npf_control_values(NPF_CONTROL_BEFORE,
            (uint64_t)li2_native_pair_owner_check(&np_owner,np_owner.p.phase),
            (uint64_t)li2_native_pair_owner_check(&npf_owner_copy,np_owner.p.phase),
            (uintptr_t)&np_owner,(uintptr_t)&npf_owner_copy);
        npf_stage_observe(NPF_CONTROL_AFTER,pc,0);
        return &npf_owner_copy;
    }
    return o;
}
void npf_owner_overflow(uintptr_t pc) {
    if(npf_control_match(18,0,NPF_PREPARED,pc)) {
        uint64_t old=np_owner.p.extensions;
        npf_stage_observe(NPF_CONTROL_BEFORE,pc,0);
        np_owner.p.extensions=UINT64_MAX;
        npf_control_values(NPF_PREPARED,old,np_owner.p.extensions,(uintptr_t)&np_owner,0);
        npf_stage_observe(NPF_CONTROL_AFTER,pc,0);
    }
}

int li2_lifecycle_pair_prepare(const struct li2_native_pair_owner *o,uintptr_t pc,int *eligible) {
    int result=npf_real_pair_prepare(o,pc,eligible);
    npf_stage_observe(NPF_PREPARED,pc,result);
    if(!result && eligible && *eligible) {
        if(npf_control_match(16,0,NPF_PREPARED,pc)) {
            unsigned index=np_life.live;uint64_t old=np_original[index].generation;
            npf_stage_observe(NPF_CONTROL_BEFORE,pc,0);
            np_original[index].generation=old^UINT64_C(1);
            npf_control_values(NPF_PREPARED,old,np_original[index].generation,
                               (uintptr_t)&np_original[index],0);
            npf_stage_observe(NPF_CONTROL_AFTER,pc,0);
        }
        npf_owner_overflow(pc);
        npf_control_hook(NPF_PREPARED,pc);
    }
    return result;
}
int li2_lifecycle_pair_publish(const struct li2_native_pair_owner *o,uintptr_t pc) {
    int result=npf_real_pair_publish(o,pc);
    npf_stage_observe(NPF_PUBLISHED,pc,result);
    if(!result)npf_control_hook(NPF_PUBLISHED,pc);
    return result;
}
int li2_lifecycle_pair_close(const struct li2_native_pair_owner *o) {
    uintptr_t pc=li2_native_pair_progress()->pc;
    npf_stage_observe(NPF_CLOSE_BEFORE,pc,0);
    int result=npf_real_pair_close(o);
    npf_stage_observe(NPF_CLOSE_AFTER,pc,result);
    return result;
}

void npf_rseq_mutate_pin(void) {
    /* Supplied retained-pin mutation after the safe prefix, at genuine NX.
       No RAW, logging, fabricated event or production setter exists here. */
    if(np_rseq.active==1 && np_rseq.registered==1 && np_rseq.registration_epoch!=UINT64_MAX)
        ++np_rseq.registration_epoch;
    __asm__ volatile("":::"memory");
}
